BEGIN; DO $$ BEGIN IF to_regprocedure('public.shipment_outbound_delivery_core_20260722(jsonb,uuid,uuid,uuid,text,text,text,text,text,date,uuid)') IS NULL OR to_regprocedure('public.inventory_lock_product(uuid)') IS NULL OR to_regprocedure('public.inventory_calculate_product_stock_v1(text,text,text)') IS NULL OR to_regprocedure('public.inventory_actor_can_change_transaction(date)') IS NULL THEN RAISE EXCEPTION 'Thieu backend an toan. Dung cai dat va kiem tra ban live.'; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='inventory_transactions' AND column_name='shipment_line_no') THEN RAISE EXCEPTION 'Thieu thu tu dong phieu. Dung cai dat va kiem tra ban live.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.shipment_outbound_delivery( p_payload jsonb, p_customer_id uuid, p_entity_id uuid, p_vehicle_id uuid DEFAULT NULL, p_driver_1_name text DEFAULT NULL, p_driver_2_name text DEFAULT NULL, p_assistant_1_name text DEFAULT NULL, p_assistant_2_name text DEFAULT NULL, p_note text DEFAULT NULL, p_shipment_date date DEFAULT (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date, p_existing_shipment_id uuid DEFAULT NULL ) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_result jsonb; v_shipment_id uuid; v_numbered_count integer; v_active_count integer; v_plan_count integer; v_product_ids uuid[]; v_product_id uuid; v_day date; v_negative record; v_previous_batch text := COALESCE(current_setting('app.inventory_batch_replace',true),'off'); BEGIN IF auth.uid() IS NULL OR NOT public.is_manager() THEN RAISE EXCEPTION 'Ban khong co quyen tao chuyen hang.' USING ERRCODE='42501'; END IF; IF p_shipment_date IS NULL OR NOT public.inventory_actor_can_change_transaction(p_shipment_date) THEN RAISE EXCEPTION 'Ban khong co quyen tao chuyen o ngay nay.' USING ERRCODE='42501'; END IF; IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'array' THEN RAISE EXCEPTION 'Du lieu chuyen hang khong hop le.'; END IF; IF jsonb_array_length(p_payload)=0 THEN RAISE EXCEPTION 'Chuyen phai co it nhat mot dong hang.'; END IF; IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload) e(item) WHERE jsonb_typeof(item)<>'object' OR NULLIF(item->>'plan_id','') IS NULL OR jsonb_typeof(item->'actual_qty') IS DISTINCT FROM 'number') THEN RAISE EXCEPTION 'Dong chuyen hang thieu ke hoach hoac so luong.'; END IF; IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload) e(item) WHERE (item->>'actual_qty')::numeric<=0) THEN RAISE EXCEPTION 'So luong xuat phai lon hon 0.'; END IF; IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload) e(item) GROUP BY (item->>'plan_id')::uuid HAVING count(*)>1) THEN RAISE EXCEPTION 'Mot ma ke hoach chi duoc xuat hien mot lan tren chuyen.'; END IF; IF p_existing_shipment_id IS NOT NULL THEN RAISE EXCEPTION 'Chuc nang ghep hang vao chuyen da tat. Hay dieu chinh tai Nhat ky giao hang.'; END IF; IF p_vehicle_id IS NULL THEN RAISE EXCEPTION 'Vui long chon xe.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_vehicle_id::text || ':' || p_shipment_date::text,20260722)); PERFORM p.id FROM public.delivery_plans p WHERE p.id IN (SELECT (item->>'plan_id')::uuid FROM jsonb_array_elements(p_payload) e(item)) AND p.deleted_at IS NULL ORDER BY p.plan_date,p.id FOR UPDATE; SELECT count(*),array_agg(DISTINCT p.product_id ORDER BY p.product_id) INTO v_plan_count,v_product_ids FROM public.delivery_plans p WHERE p.id IN (SELECT (item->>'plan_id')::uuid FROM jsonb_array_elements(p_payload) e(item)) AND p.deleted_at IS NULL AND p.plan_date=p_shipment_date; IF v_plan_count<>jsonb_array_length(p_payload) THEN RAISE EXCEPTION 'Co ke hoach khong con ton tai hoac khac ngay xuat. Tai lai trang va chon lai.'; END IF; FOREACH v_product_id IN ARRAY v_product_ids LOOP PERFORM public.inventory_lock_product(v_product_id); END LOOP; PERFORM set_config('app.inventory_batch_replace','on',true); v_result := public.shipment_outbound_delivery_core_20260722(p_payload,p_customer_id,p_entity_id,p_vehicle_id,p_driver_1_name,p_driver_2_name,p_assistant_1_name,p_assistant_2_name,p_note,p_shipment_date,p_existing_shipment_id); v_shipment_id := NULLIF(v_result->>'shipment_id','')::uuid; IF v_shipment_id IS NULL THEN RAISE EXCEPTION 'Khong nhan duoc ma chuyen de luu thu tu dong.'; END IF; UPDATE public.inventory_transactions t SET shipment_line_no=x.line_no::integer FROM jsonb_array_elements(p_payload) WITH ORDINALITY AS x(item,line_no) WHERE t.shipment_id=v_shipment_id AND t.delivery_plan_id=(x.item->>'plan_id')::uuid AND t.tx_type='out' AND t.adjusted_from_transaction_id IS NULL AND t.deleted_at IS NULL; GET DIAGNOSTICS v_numbered_count=ROW_COUNT; SELECT count(*) INTO v_active_count FROM public.inventory_transactions t WHERE t.shipment_id=v_shipment_id AND t.tx_type='out' AND t.adjusted_from_transaction_id IS NULL AND t.deleted_at IS NULL; IF v_numbered_count<>v_active_count OR v_active_count<>jsonb_array_length(p_payload) THEN RAISE EXCEPTION 'Khong luu du dong cua chuyen; toan bo thao tac da duoc hoan tac.'; END IF; IF EXISTS (SELECT 1 FROM public.inventory_transactions t WHERE t.shipment_id=v_shipment_id AND t.deleted_at IS NULL AND NOT (t.product_id=ANY(v_product_ids))) THEN RAISE EXCEPTION 'Ma hang tren chuyen da thay doi. Toan bo thao tac da duoc hoan tac.'; END IF; PERFORM set_config('app.inventory_batch_replace',v_previous_batch,true); FOR v_day IN SELECT p_shipment_date UNION SELECT t.tx_date::date FROM public.inventory_transactions t WHERE t.deleted_at IS NULL AND t.product_id=ANY(v_product_ids) AND t.tx_date::date>=p_shipment_date ORDER BY 1 LOOP WITH day_stock AS MATERIALIZED ( SELECT s.product_id,s.current_qty FROM public.inventory_calculate_product_stock_v1(v_day::text,'1970-01-01',(v_day+1)::text) s ) SELECT s.product_id,s.current_qty,COALESCE(p.sku,'') || CASE WHEN p.name IS NULL THEN '' ELSE ' - ' || p.name END AS label INTO v_negative FROM day_stock s LEFT JOIN public.products p ON p.id=s.product_id WHERE s.product_id=ANY(v_product_ids) AND s.current_qty<0 AND (v_day=p_shipment_date OR EXISTS (SELECT 1 FROM public.inventory_transactions t WHERE t.product_id=s.product_id AND t.deleted_at IS NULL AND t.tx_date::date=v_day)) ORDER BY s.product_id LIMIT 1; IF FOUND THEN RAISE EXCEPTION 'Bi chan de bao ve kho: ma hang "%", ngay %, ton tong theo ma bi am %.',COALESCE(v_negative.label,v_negative.product_id::text),v_day,v_negative.current_qty; END IF; END LOOP; RETURN v_result; EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.inventory_batch_replace',v_previous_batch,true); RAISE; END $$; REVOKE ALL ON FUNCTION public.shipment_outbound_delivery_core_20260722(jsonb,uuid,uuid,uuid,text,text,text,text,text,date,uuid) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.shipment_outbound_delivery(jsonb,uuid,uuid,uuid,text,text,text,text,text,date,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.shipment_outbound_delivery(jsonb,uuid,uuid,uuid,text,text,text,text,text,date,uuid) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
